116						// The big number lives in a legal change record that
117						// precedes the corrupt removals array.
118						return p + `"name":"A","note":1e400,"upstreams":[]}],"removals":["ok","b","c` + "\xc3" + `"]}`
119					}
120					return p + `"removals":["ok","b","c` + "\xc3" + `"]}`
121				},
122				`"removals"`, `index 2`, "invalid UTF-8 bytes",
123			},
124			"unpaired surrogate in a removals entry": {
125				func(p string) string {
