145							planBefore := readFile(t, planPath)
146	
147							stdout, stderr, exit := runBatchCLI(t, verb, graphPath, planPath)
148							if exit == 0 {
149								t.Fatalf("%s exit = 0, want non-zero; stdout = %s", verb, stdout)
150							}
