215		for name, tc := range cases {
216			t.Run(name, func(t *testing.T) {
217				for _, verb := range []string{"preview", "apply"} {
218					t.Run(verb, func(t *testing.T) {
219						graphPath := writeFile(t, "graph.json", graphWithReplacementCharRoot)
220						planPath := writeFile(t, "plan.json", tc.plan)
221						graphBefore := readFile(t, graphPath)
222						planBefore := readFile(t, planPath)
223	
224						stdout, stderr, exit := runBatchCLI(t, verb, graphPath, planPath)
225						if exit == 0 {
226							t.Fatalf("%s exit = 0, want non-zero; stdout = %s", verb, stdout)
227						}
228						if stdout != "" {
229							t.Errorf("%s stdout = %q, want empty on rejection", verb, stdout)
230						}
231						for _, want := range []string{planPath, `"removals"`, "index 0", tc.reason} {
232							if !strings.Contains(stderr, want) {
