238						}
239						if got := readFile(t, graphPath); got != graphBefore {
240							t.Errorf("graph file changed:\n got %s\nwant %s", got, graphBefore)
241						}
242						if got := readFile(t, planPath); got != planBefore {
243							t.Errorf("plan file changed")
244						}
245						graph := mustReadGraphCLI(t, graphPath)
246						if _, ok := graph["源�"]; !ok {
247							t.Fatal("the dataset really named 源� was deleted by a corrupted removal")
248						}
249						if _, ok := graph["keep"]; !ok {
250							t.Fatal("the unrelated dataset keep disappeared")
251						}
252					})
253				}
254			})
255		}
256	}
