258	// TestCLIBigNumbersWholeBatchRejectedBeforeAnyChange: with a big number in
259	// an ignored field, a legal adjustment that WOULD change the graph, and a
260	// corrupt removal later in the same plan, apply must reject the whole batch
261	// — the legal adjustment must not take effect either, and the real "源�"
262	// must survive. Preview behaves identically and touches neither file.
263	func TestCLIBigNumbersWholeBatchRejectedBeforeAnyChange(t *testing.T) {
264		// down really depends on 源�; the legal change would clear that edge.
265		graphContent := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"down","upstreams":["源�"]}]}`
266		for _, corrupt := range []struct {
267			name    string
268			removal string
269			reason  string
270		}{
271			{"broken byte", `"源` + "\xff" + `"`, "invalid UTF-8 bytes"},
272			{"lone surrogate", `"源\ud800"`, "unpaired surrogate"},
273		} {
274			t.Run(corrupt.name, func(t *testing.T) {
275				planContent := `{"note":1e400,"changes":[{"name":"down","upstreams":[],"meta":[1e999]}],` +
276					`"removals":[` + corrupt.removal + `]}`
277				for _, verb := range []string{"preview", "apply"} {
278					t.Run(verb, func(t *testing.T) {
279						graphPath := writeFile(t, "graph.json", graphContent)
280						planPath := writeFile(t, "plan.json", planContent)
281						graphBefore := readFile(t, graphPath)
282	
283						stdout, stderr, exit := runBatchCLI(t, verb, graphPath, planPath)
284						if exit == 0 {
285							t.Fatalf("%s exit = 0, want non-zero; stdout = %s", verb, stdout)
286						}
287						if stdout != "" {
288							t.Errorf("%s stdout = %q, want empty", verb, stdout)
289						}
290						for _, want := range []string{planPath, `"removals"`, "index 0", corrupt.reason} {
291							if !strings.Contains(stderr, want) {
292								t.Errorf("stderr = %q, want it to contain %q", stderr, want)
293							}
294						}
295						// Graph bytes unchanged: neither the legal change nor the
296						// corrupted removal took effect.
297						if got := readFile(t, graphPath); got != graphBefore {
298							t.Errorf("graph file changed after rejected %s:\n got %s\nwant %s", verb, got, graphBefore)
299						}
300						graph := mustReadGraphCLI(t, graphPath)
301						if _, ok := graph["源�"]; !ok {
302							t.Fatal("the dataset really named 源� must survive")
303						}
304						if parents := graph["down"].Parents; len(parents) != 1 || parents[0] != "源�" {
305							t.Fatalf("down.Parents = %v, the legal change must not have taken effect, want [源�]", parents)
306						}
307					})
308				}
309			})
310		}
311	}
312	
313	// TestCLILegalRemovalOfReplacementCharWithBigNumbers: once the removal
314	// really names "源�" — written directly or with equivalent JSON escapes —
315	// and carries the same big-number additions, preview and apply succeed: the
316	// real name shows up in removedDatasets, and apply leaves exactly the
317	// surviving graph on disk.
318	func TestCLILegalRemovalOfReplacementCharWithBigNumbers(t *testing.T) {
319		direct := `{"note":1e400,"meta":[1e999,{"z":-1e400}],"removals":["源�"]}`
320		escaped := `{"note":1e400,"meta":[1e999,{"z":-1e400}],"removals":["\u6e90\ufffd"]}`
321		if direct == escaped {
322			t.Fatal("test premise broken: the two spellings must differ on disk")
323		}
324		for name, planContent := range map[string]string{"direct": direct, "escaped": escaped} {
325			t.Run(name, func(t *testing.T) {
326				// Preview first: report carries the real removal, graph untouched.
327				previewGraph := writeFile(t, "graph-preview.json", graphWithReplacementCharRoot)
328				planPath := writeFile(t, "plan.json", planContent)
329				graphBefore := readFile(t, previewGraph)
330				stdout, stderr, exit := runBatchCLI(t, "preview", previewGraph, planPath)
331				if exit != 0 {
332					t.Fatalf("preview exit = %d, stderr = %s", exit, stderr)
333				}
334				if got := mustParseReport(t, stdout).RemovedDatasets; len(got) != 1 || got[0] != "源�" {
335					t.Errorf("preview removedDatasets = %v, want [源�]", got)
336				}
337				if got := readFile(t, previewGraph); got != graphBefore {
338					t.Errorf("preview changed the graph file")
339				}
340	
341				// Apply: the real dataset is removed, keep survives, and applying
342				// the same plan once more is still a successful no-op.
343				applyGraph := writeFile(t, "graph-apply.json", graphWithReplacementCharRoot)
344				stdout, stderr, exit = runBatchCLI(t, "apply", applyGraph, planPath)
345				if exit != 0 {
346					t.Fatalf("apply exit = %d, stderr = %s", exit, stderr)
347				}
348				if got := mustParseReport(t, stdout).RemovedDatasets; len(got) != 1 || got[0] != "源�" {
349					t.Errorf("apply removedDatasets = %v, want [源�]", got)
350				}
351				graph := mustReadGraphCLI(t, applyGraph)
352				if _, ok := graph["源�"]; ok {
353					t.Fatal("the dataset really named 源� must be gone after apply")
354				}
355				if _, ok := graph["keep"]; !ok {
356					t.Fatal("the unrelated dataset keep must survive")
357				}
358	
359				stdout, stderr, exit = runBatchCLI(t, "apply", applyGraph, planPath)
360				if exit != 0 {
361					t.Fatalf("re-apply exit = %d, stderr = %s", exit, stderr)
362				}
363				if got := mustParseReport(t, stdout).RemovedDatasets; len(got) != 0 {
364					t.Errorf("re-apply must report no removals, got %v", got)
365				}
366			})
367		}
368	}
369	
370	// TestCLIUnknownFieldsDoNotChangeReportOrGraph: for a plan whose business
371	// names are all legal, adding or removing the additional information
372	// (oversized numbers at the top level, nested in unknown objects/arrays, or
373	// inside change records) changes neither preview's report bytes nor apply's
374	// report bytes and the final graph file.
375	func TestCLIUnknownFieldsDoNotChangeReportOrGraph(t *testing.T) {
376		graphContent := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"源�","upstreams":[]}]}`
377		plans := map[string]string{
378			"plain": `{"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`,
379			"big number at top": `{"note":1e400,` +
380				`"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`,
381			"big numbers nested everywhere": `{"meta":{"x":[1e400,{"y":1e999}]},"changes":[` +
382				`{"name":"B","upstreams":["源�"],"vals":[1e999,-1e400],"note":{}}],` +
383				`"removals":["A"],"tail":[2e400]}`,
384		}
385	
386		// Preview reports must be byte-identical across the plan spellings.
387		var basePreview string
388		for name, planContent := range plans {
389			graphPath := writeFile(t, filepath.Join(name+"-preview-graph.json"), graphContent)
390			planPath := writeFile(t, filepath.Join(name+"-plan.json"), planContent)
391			stdout, stderr, exit := runBatchCLI(t, "preview", graphPath, planPath)
392			if exit != 0 {
393				t.Fatalf("preview %s exit = %d, stderr = %s", name, exit, stderr)
394			}
395			if basePreview == "" {
396				basePreview = stdout
397			} else if stdout != basePreview {
398				t.Fatalf("preview %s report differs from plain:\n%s\n%s", name, stdout, basePreview)
399			}
400		}
401	
402		// Apply: identical reports and identical resulting graph bytes.
403		var baseApply, baseGraph string
404		for name, planContent := range plans {
405			graphPath := writeFile(t, filepath.Join(name+"-apply-graph.json"), graphContent)
406			planPath := writeFile(t, filepath.Join(name+"-apply-plan.json"), planContent)
407			stdout, stderr, exit := runBatchCLI(t, "apply", graphPath, planPath)
408			if exit != 0 {
409				t.Fatalf("apply %s exit = %d, stderr = %s", name, exit, stderr)
410			}
411			finalGraph := readFile(t, graphPath)
412			if baseApply == "" {
413				baseApply, baseGraph = stdout, finalGraph
414			} else {
415				if stdout != baseApply {
416					t.Fatalf("apply %s report differs from plain:\n%s\n%s", name, stdout, baseApply)
417				}
418				if finalGraph != baseGraph {
419					t.Fatalf("apply %s graph bytes differ from plain:\n%s\n%s", name, finalGraph, baseGraph)
420				}
421			}
422		}
423	}
