21	// assertNameCorruption rejects a plan with the name-encoding error for the
22	// given field/position and corruption kind, and — just as importantly — with
23	// none of the errors a masked scan could surface instead.
24	func assertNameCorruption(t *testing.T, data, field, location, reason string) {
25		t.Helper()
26		_, err := UnmarshalPlan([]byte(data))
27		if !errors.Is(err, ErrInvalidArgument) {
28			t.Fatalf("UnmarshalPlan err = %v, want ErrInvalidArgument naming the corrupt name", err)
29		}
30		msg := err.Error()
31		if !strings.Contains(msg, reason) {
32			t.Errorf("err = %q, want it to say %q", msg, reason)
33		}
34		if !strings.Contains(msg, field) {
35			t.Errorf("err = %q, want it to name field %q", msg, field)
36		}
37		if !strings.Contains(msg, location) {
38			t.Errorf("err = %q, want it to locate %q", msg, location)
39		}
40		switch reason {
41		case "invalid UTF-8 bytes":
42			if strings.Contains(msg, "surrogate") {
43				t.Errorf("err = %q, byte corruption must not be reported as a surrogate problem", msg)
44			}
45		case "unpaired surrogate":
46			if strings.Contains(msg, "invalid UTF-8 bytes") {
47				t.Errorf("err = %q, a surrogate problem must not be reported as invalid bytes", msg)
48			}
49		}
50		// A large number in a skipped unknown field must not be mistaken for the
51		// problem, and the plan must not fall through to later validation: the
52		// name defect is the only reported reason.
53		for _, masked := range []string{"invalid plan JSON", "cannot unmarshal number", "does not exist in the final graph", "no change"} {
54			if strings.Contains(msg, masked) {
55				t.Errorf("err = %q, name corruption was masked by %q", msg, masked)
