198			t.Run(c.name, func(t *testing.T) {
199				var wantMsg string
200				for decoName, deco := range decorate {
201					_, err := UnmarshalPlan([]byte(deco(c.plan)))
202					if err == nil {
203						t.Fatalf("%s: corrupt plan accepted", decoName)
204					}
