215	// TestPlanBigNumberBeforeCorruptRemovalNeverDeletes: the removal case keeps
216	// the user's original intent — a removal written as "源" plus a broken byte
217	// or a lone surrogate must not be rewritten into the genuinely existing
218	// dataset "源�" and delete it, and a corrupted name matching no dataset at
219	// all must not be accepted as the no-op "delete a nonexistent name" success.
220	// A big unknown field placed before the removal changes none of this.
221	func TestPlanBigNumberBeforeCorruptRemovalNeverDeletes(t *testing.T) {
222		graph := buildGraph(t, P("源�"), P("keep"))
223		before := snapshotGraph(graph)
224	
225		cases := map[string]string{
226			"broken byte would collide with real 源�":    `{"note":1e400,"removals":["源` + "\xff" + `"]}`,
227			"lone surrogate would collide with real 源�": `{"meta":[1e999],"removals":["源\ud800"]}`,
228			"low-before-high surrogate would collide":   `{"note":{"x":1e400},"removals":["源\udc00\ud800"]}`,
229			"broken byte names no dataset at all":       `{"note":1e400,"removals":["ghost` + "\xff" + `"]}`,
230			"lone surrogate names no dataset at all":    `{"bag":[1e400],"removals":["ghost\ud800"]}`,
231			"broken byte after a legal change": `{"note":1e400,"changes":[{"name":"keep","upstreams":[]}],` +
232				`"removals":["源` + "\xff" + `"]}`,
233		}
234		for name, data := range cases {
235			t.Run(name, func(t *testing.T) {
236				if _, err := UnmarshalPlan([]byte(data)); err == nil {
237					t.Fatal("corrupt removal name must reject the plan at parse time")
238				}
