249	// TestPlanGenuineReplacementCharWithBigNumbersSucceeds: when the removal
250	// really names the existing dataset "源�" — written directly or with
251	// equivalent JSON escapes — and nothing would still reference it, the same
252	// big-number additions stay legal and the real name enters the actual
253	// removal result for both preview and apply.
254	func TestPlanGenuineReplacementCharWithBigNumbersSucceeds(t *testing.T) {
255		direct := []byte(`{"note":1e400,"meta":[1e999,{"z":-1e400}],"removals":["源�"]}`)
256		// The same removal written with literal JSON \u escapes for both 源 and
257		// � — different bytes on disk, the same dataset once decoded.
258		escaped := []byte(`{"note":1e400,"meta":[1e999,{"z":-1e400}],"removals":["\u6e90\ufffd"]}`)
259	
260		planDirect, err := UnmarshalPlan(direct)
