299	// TestPlanUnknownFieldsDoNotChangeReport: for a plan whose business names
300	// are all legal, adding or removing the additional information — oversized
301	// numbers, unknown objects and arrays, at the top level or inside records —
302	// changes neither the decoded Plan nor the marshaled report nor the graph an
303	// apply produces.
304	func TestPlanUnknownFieldsDoNotChangeReport(t *testing.T) {
305		graph := func() map[string]*Lineage {
306			return buildGraph(t, P("A"), P("B", "A"), P("源�"))
307		}
308		plain := `{"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`
309		variants := map[string]string{
310			"plain": plain,
311			"big number at top": `{"note":1e400,` +
312				`"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`,
313			"big numbers nested everywhere": `{"meta":{"x":[1e400,{"y":1e999}]},"changes":[` +
314				`{"name":"B","upstreams":["源�"],"vals":[1e999,-1e400],"note":{}}],` +
315				`"removals":["A"],"tail":[2e400]}`,
316			"equivalent escapes plus big numbers": `{"note":1e400,"changes":[` +
317				`{"name":"\u0042","upstreams":["\u6e90\ufffd"]}],"removals":["\u0041"]}`,
318		}
319	
320		basePlan, err := UnmarshalPlan([]byte(plain))
321		if err != nil {
322			t.Fatalf("plain plan rejected: %v", err)
323		}
324		baseGraph := graph()
325		baseReport, err := PreviewBatch(baseGraph, basePlan)
326		if err != nil {
327			t.Fatalf("PreviewBatch plain: %v", err)
328		}
329		baseJSON, _ := json.Marshal(baseReport)
330	
331		if _, err := ApplyBatch(baseGraph, basePlan); err != nil {
332			t.Fatalf("ApplyBatch plain: %v", err)
333		}
334		baseGraphBytes, err := MarshalGraphFile(baseGraph)
335		if err != nil {
