370	
371	// TestPlanUnknownFieldConfusionStaysIgnoredWithBigNumbers: even with
372	// oversized numbers present, anything nested inside an unknown field stays
373	// additional information: its own corrupt strings, repeated field names, and
374	// content shaped exactly like adjustment records must not widen the
375	// name-encoding check to those strings — the business names around them are
376	// the only ones judged.
377	func TestPlanUnknownFieldConfusionStaysIgnoredWithBigNumbers(t *testing.T) {
378		cases := map[string]string{
379			"corrupt strings nested next to big numbers": `{"note":1e400,"meta":["a` + "\xff" + `",{"k":"\ud800"}],"changes":[{"name":"A","upstreams":[]}]}`,
