1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	
9		"github.com/asdhoaiqqq/chainledger-governance/chainledger"
10	)
11	
12	// These tests pin the CLI behavior when a graph's raw name literals are
13	// corrupt (invalid UTF-8 bytes or unpaired \u surrogate escapes): preview,
14	// apply, and snapshot reject a corrupt source graph — non-zero exit, empty
15	// stdout, stderr naming the file, whether the problem is in a dataset name
16	// or an upstream, and the zero-based record (and upstream array) position;
17	// the source graph and any existing target keep every byte and no snapshot
18	// is created. compare and trace reject a snapshot that embeds such a graph
19	// before printing any report.
20	
21	// writeRawFile writes arbitrary bytes (the test graph names carry raw
22	// invalid UTF-8) to a file in the test's temp directory.
23	func writeRawFile(t *testing.T, name string, data []byte) string {
24		t.Helper()
25		path := filepath.Join(t.TempDir(), name)
26		if err := os.WriteFile(path, data, 0o644); err != nil {
27			t.Fatalf("WriteFile %q: %v", name, err)
28		}
29		return path
30	}
31	
32	func TestCLIGraphCorruptNamesRejectedByPreviewApplySnapshot(t *testing.T) {
33		cases := map[string]struct {
34			graph    []byte
35			field    string
36			location string
37			reason   string
38		}{
39			"invalid bytes in dataset name": {
40				[]byte(`{"datasets":[{"name":"源` + "\xff" + `","upstreams":[]}]}`),
41				`"name"`, `index 0 of "datasets"`, "invalid UTF-8 bytes",
42			},
43			"invalid bytes in upstream entry": {
44				[]byte(`{"datasets":[{"name":"源","upstreams":[]},{"name":"d","upstreams":["源` + "\xfe" + `"]}]}`),
45				`"upstreams"`, `index 0 in the dataset record at index 1 of "datasets"`, "invalid UTF-8 bytes",
46			},
47			"lone surrogate upstream colliding with a genuine dataset": {
48				// Root genuinely named 源�; the edge written as 源 + lone \uD800
49				// would resolve to it after the decoder's rewrite.
50				[]byte(`{"datasets":[{"name":"源�","upstreams":[]},{"name":"d","upstreams":["源\uD800"]}]}`),
51				`"upstreams"`, `index 0 in the dataset record at index 1 of "datasets"`, "unpaired surrogate",
52			},
53			"lone low surrogate in dataset name": {
54				[]byte(`{"datasets":[{"name":"a\uDC00","upstreams":[]}]}`),
55				`"name"`, `index 0 of "datasets"`, "unpaired surrogate",
56			},
57			"low-before-high upstream with no possible collision": {
58				// Nothing is named the rewrite target; the graph must still fail.
59				[]byte(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["ghost\uDC00\uD83D"]}]}`),
60				`"upstreams"`, `index 0 in the dataset record at index 1 of "datasets"`, "unpaired surrogate",
61			},
62		}
63		planPath := writeFile(t, "plan.json", `{"changes":[]}`)
64	
